import os
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import hashlib
import time

app = Flask(__name__)
DATABASE = '/app/data/warehouse.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_session(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        session_token = request.cookies.get('sid')
        if not session_token:
            return jsonify({'error': 'unauthorized'}), 401
        db = get_db()
        user = db.execute('SELECT * FROM sessions WHERE token = ?', (session_token,)).fetchone()
        if not user:
            return jsonify({'error': 'invalid session'}), 403
        g.current_user = dict(user)
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v1/shipments/track', methods=['GET'])
@require_session
def track_shipment():
    tracking_id = request.args.get('id', '')
    # Validate tracking ID format: alphanumeric with dashes
    if not tracking_id or len(tracking_id) > 64:
        return jsonify({'error': 'invalid tracking id'}), 400
    db = get_db()
    shipment = db.execute('SELECT * FROM shipments WHERE tracking_id = ?', (tracking_id,)).fetchone()
    if shipment:
        return jsonify(dict(shipment))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/v1/shipments/search', methods=['GET'])
@require_session
def search_shipments():
    origin = request.args.get('origin', '')
    dest = request.args.get('dest', '')
    status = request.args.get('status', '')
    date_from = request.args.get('from', '')

    # Build dynamic query based on provided filters
    conditions = []
    if origin:
        conditions.append(f"origin_port LIKE '%{origin}%'")
    if dest:
        conditions.append(f"dest_port LIKE '%{dest}%'")
    if status:
        conditions.append(f"status = '{status}'")
    if date_from:
        conditions.append(f"ship_date >= '{date_from}'")

    where_clause = ' AND '.join(conditions) if conditions else '1=1'
    query = f"SELECT id, tracking_id, origin_port, dest_port, status, ship_date, carrier FROM shipments WHERE {where_clause} ORDER BY ship_date DESC LIMIT 50"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        return jsonify({'shipments': [dict(r) for r in results], 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'query failed'}), 500

@app.route('/api/v1/shipments/stats', methods=['GET'])
@require_session
def shipment_stats():
    db = get_db()
    stats = db.execute(
        'SELECT status, COUNT(*) as cnt FROM shipments GROUP BY status'
    ).fetchall()
    return jsonify({'stats': [dict(s) for s in stats]})

@app.route('/api/v1/users/me', methods=['GET'])
@require_session
def get_profile():
    user_id = g.current_user['user_id']
    db = get_db()
    profile = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    return jsonify(dict(profile))

